// 실제 게임 화면(2026-11-10, 사용자 제공)에서 잘라 낸 미니맵 시험 데이터. 회색조 0~255, 행 우선, gzip 뒤 base64.
// withRune: 사용자가 보낸 미니맵 199×100. 룬(분홍빛 보라 마름모, 반지름 5)은 (41,75)부터 11×11
// noRune:   첫 스크린샷(1352×751)의 미니맵 200×95(원래 화면 x=5, y=60부터). 룬 없음. 다른 플레이어(분홍 원)·포털(초록 원)·나(노란 원)가 있다
// rune:     withRune의 (41,75)부터 11×11 = 내장 룬 아이콘 PRESET_ICONS.rune[0]과 같은 조각
import zlib from 'node:zlib';
export const RUNE_MINIMAP={
  withRune:{w:199,h:100,gray:''},
  noRune:{w:200,h:95,gray:''},
  rune:{w:11,h:11,gray:'H4sIAAAAAAACE3Nxc3HpP9vv4uLiYmBo0HyS4WSzoaGBiFjJQYY5DAeLlXiFQKw5cxgOVrE1ngCx5sxhONNzBsKaM4fh7JQLUNGL0+16T4PVnu6yszZvP8Uwh+F0u7m5tbVt9xmGM922trZWVlZWnac7raysrQGtnihEeQAAAA=='},
  at:{x:41,y:75},
};
export const grayOf=o=>Float32Array.from(zlib.gunzipSync(Buffer.from(o.gray,'base64')));
